import "core-js/modules/es.array.push.js";
import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import "core-js/modules/esnext.iterator.map.js";
import AdminNavigationBar from './AdminNavigationBar.vue';
import { ref, computed, onMounted } from "vue";
import { db } from "@/firebase";
import { collection, addDoc, updateDoc, deleteDoc, doc, onSnapshot, serverTimestamp } from "firebase/firestore";
import { useRouter } from "vue-router";
export default {
  components: {
    AdminNavigationBar
  },
  setup() {
    const contracts = ref([]);
    const loading = ref(true);
    const isModalOpen = ref(false);
    const isConfirmingDelete = ref(false);
    const editMode = ref(false);
    const searchQuery = ref("");
    const statusFilter = ref("all");
    const fileName = ref("");
    const selectedFile = ref(null);
    const activeContract = ref({});
    const contractData = ref({
      supplier: "",
      poNumber: "",
      status: "Pending",
      value: "",
      startDate: "",
      endDate: "",
      description: ""
    });

    // Modal state for minimal modal
    const activeModal = ref(null); // 'view' | 'edit' | 'delete' | null
    const selectedContract = ref(null);

    // Minimal modal handlers
    async function saveChanges() {
      if (selectedContract.value && selectedContract.value.id) {
        try {
          const contractRef = doc(db, "contracts", selectedContract.value.id);
          await updateDoc(contractRef, {
            ...selectedContract.value,
            updatedAt: serverTimestamp()
          });
          showNotification("Contract updated successfully!");
        } catch (error) {
          console.error("Error updating contract:", error);
          showNotification("Failed to update contract. Please try again.", "error");
        }
      }
      activeModal.value = null;
      selectedContract.value = null;
    }
    async function confirmDeleteModal() {
      if (selectedContract.value && selectedContract.value.id) {
        try {
          const contractRef = doc(db, "contracts", selectedContract.value.id);
          await deleteDoc(contractRef);
          showNotification("Contract deleted successfully!");
        } catch (error) {
          console.error("Error deleting contract:", error);
          showNotification("Failed to delete contract. Please try again.", "error");
        }
      }
      activeModal.value = null;
      selectedContract.value = null;
    }
    const router = useRouter();
    const navigateToAddContract = () => {
      router.push({
        name: "AddContract"
      });
    };

    // Computed values for stats
    const pendingContractsCount = computed(() => contracts.value.filter(contract => contract.status === "Pending").length);
    const activeContractsCount = computed(() => contracts.value.filter(contract => contract.status === "Active").length);
    const completedContractsCount = computed(() => contracts.value.filter(contract => contract.status === "Completed").length);
    const filteredContracts = computed(() => {
      let result = [...contracts.value];

      // Apply status filter
      if (statusFilter.value !== "all") {
        result = result.filter(contract => contract.status === statusFilter.value);
      }

      // Apply search query
      if (searchQuery.value) {
        const query = searchQuery.value.toLowerCase();
        result = result.filter(contract => contract.supplier.toLowerCase().includes(query) || contract.poNumber.toLowerCase().includes(query) || contract.description && contract.description.toLowerCase().includes(query));
      }
      return result;
    });
    const fetchContracts = async () => {
      try {
        loading.value = true;

        // Set up real-time listener for contracts collection
        const unsubscribe = onSnapshot(collection(db, "contracts"), snapshot => {
          contracts.value = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          }));
          loading.value = false;
        });

        // Return unsubscribe function for cleanup
        return unsubscribe;
      } catch (error) {
        console.error("Error fetching contracts:", error);
        showNotification("Failed to fetch contracts. Please try again.", "error");
        loading.value = false;
      }
    };
    const showAddModal = () => {
      editMode.value = false;
      resetForm();
      isModalOpen.value = true;
    };
    const closeModal = () => {
      isModalOpen.value = false;
      activeModal.value = null;
      selectedContract.value = null;
    };
    const resetForm = () => {
      contractData.value = {
        supplier: "",
        poNumber: "",
        status: "Pending",
        value: "",
        startDate: "",
        endDate: "",
        description: ""
      };
      fileName.value = "";
      selectedFile.value = null;
    };

    // Replace openModal logic to use minimalistic modal
    const openModal = (type, contract) => {
      activeModal.value = type; // 'view', 'edit', or 'delete'
      selectedContract.value = {
        ...contract
      };
      contractData.value = {
        ...contract
      };
    };
    const submitContract = async () => {
      try {
        if (editMode.value) {
          // Update existing contract
          const contractRef = doc(db, "contracts", contractData.value.id);
          await updateDoc(contractRef, {
            ...contractData.value,
            updatedAt: serverTimestamp()
          });
          showNotification("Contract updated successfully!");
        } else {
          // Add new contract
          await addDoc(collection(db, "contracts"), {
            ...contractData.value,
            createdAt: serverTimestamp()
          });
          showNotification("Contract added successfully!");
        }
        closeModal();
      } catch (error) {
        console.error("Error saving contract:", error);
        showNotification("Failed to save contract. Please try again.", "error");
      }
    };
    const confirmDelete = contract => {
      activeContract.value = contract;
      isConfirmingDelete.value = true;
    };
    const cancelDelete = () => {
      isConfirmingDelete.value = false;
    };
    const deleteContract = async () => {
      try {
        const contractRef = doc(db, "contracts", activeContract.value.id);
        await deleteDoc(contractRef);
        showNotification("Contract deleted successfully!");
        isConfirmingDelete.value = false;
      } catch (error) {
        console.error("Error deleting contract:", error);
        showNotification("Failed to delete contract. Please try again.", "error");
      }
    };
    const handleFileUpload = event => {
      const file = event.target.files[0];
      if (file) {
        selectedFile.value = file;
        fileName.value = file.name;
      }
    };
    const formatDate = timestamp => {
      if (!timestamp) return "N/A";

      // If timestamp is a Firestore Timestamp, convert to JS Date
      const date = timestamp.toDate ? timestamp.toDate() : new Date(timestamp);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric"
      });
    };
    const formatCurrency = amount => {
      if (!amount) return "$0.00";
      return new Intl.NumberFormat("en-US", {
        style: "currency",
        currency: "USD"
      }).format(amount);
    };
    const showNotification = (message, type = "success") => {
      // Create notification element
      const notification = document.createElement("div");
      notification.className = `notification ${type}`;
      notification.textContent = message;
      document.body.appendChild(notification);

      // Add animation class after a short delay
      setTimeout(() => {
        notification.classList.add("show");
      }, 10);

      // Remove notification after timeout
      setTimeout(() => {
        notification.classList.remove("show");
        setTimeout(() => {
          document.body.removeChild(notification);
        }, 300);
      }, 3000);
    };
    onMounted(fetchContracts);
    return {
      contracts,
      loading,
      isModalOpen,
      isConfirmingDelete,
      editMode,
      searchQuery,
      statusFilter,
      contractData,
      activeContract,
      fileName,
      pendingContractsCount,
      activeContractsCount,
      completedContractsCount,
      filteredContracts,
      showAddModal,
      closeModal,
      openModal,
      submitContract,
      confirmDelete,
      cancelDelete,
      deleteContract,
      handleFileUpload,
      formatDate,
      formatCurrency,
      navigateToAddContract,
      activeModal,
      selectedContract,
      saveChanges,
      confirmDeleteModal
    };
  }
};
